{"path": "/workspace/server.mjs", "content": "// Small book-tracking app. No accounts, no database — books are stored in books.json.
// Run: node server.mjs  (then open http://localhost:3000)

import { createServer } from 'node:http';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const PORT = process.env.PORT || 3000;
const DATA_FILE = process.env.DATA_FILE || join(process.cwd(), 'books.json');
const __dirname = dirname(fileURLToPath(import.meta.url));

// --- Storage ---------------------------------------------------------------

/** @typedef {{id:string,title:string,author:string,notes:string,finished:boolean,addedAt:string}} Book */

/** @returns {Promise<Book[]>} */
async function loadBooks() {
  try {
    const raw = await readFile(DATA_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    if (err.code === 'ENOENT' || err.name === 'SyntaxError') return [];
    throw err;
  }
}

/** @param {Book[]} books */
async function saveBooks(books) {
  await mkdir(dirname(DATA_FILE), { recursive: true });
  await writeFile(DATA_FILE, JSON.stringify(books, null, 2), 'utf8');
}

// --- HTML helpers ----------------------------------------------------------

const escapeMap = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => escapeMap[c]);
// notes are free text; preserve line breaks in the detail view
const escMulti = (s) => esc(s).replace(/\r?\n/g, '<br>');

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${esc(title)} · Book Tracker</title>
  <style>
    :root { color-scheme: light; }
    * { box-sizing: border-box; }
    body { font: 16px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
           max-width: 720px; margin: 0 auto; padding: 24px 16px 64px; color: #1a1a1a; }
    a { color: #3a5a8c; }
    h1 { font-size: 1.6rem; margin: 0 0 1rem; }
    h2 { font-size: 1.15rem; margin: 2rem 0 0.75rem; border-bottom: 1px solid #eee; padding-bottom: 0.25rem; }
    .book { padding: 0.75rem 0; border-bottom: 1px solid #f0f0f0; display: flex; justify-content: space-between; gap: 12px; align-items: baseline; }
    .book .meta { color: #666; font-size: 0.9rem; }
    .muted { color: #888; }
    form { margin: 1rem 0; }
    label { display: block; font-weight: 600; margin: 0.75rem 0 0.2rem; font-size: 0.9rem; }
    input, textarea { width: 100%; padding: 8px 10px; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
    textarea { min-height: 90px; resize: vertical; }
    button { margin-top: 1rem; padding: 8px 16px; font: inherit; font-weight: 600; border: 0; border-radius: 6px;
             background: #3a5a8c; color: #fff; cursor: pointer; }
    button.secondary { background: #e7e7e7; color: #333; }
    .actions form { display: inline; margin: 0; }
    .actions button { margin: 0 0 0 8px; padding: 4px 10px; font-size: 0.85rem; }
    .share { margin-top: 1.5rem; padding: 0.75rem 1rem; background: #f6f8fb; border-radius: 6px; font-size: 0.9rem; }
    .share input { font: inherit; }
    .empty { color: #999; font-style: italic; padding: 0.5rem 0; }
    .back { margin-bottom: 1.5rem; }
  </style>
</head>
<body>
  <h1><a href="/" style="color:inherit;text-decoration:none">Book Tracker</a></h1>
  ${body}
</body>
</html>`;
}

// --- Pages -----------------------------------------------------------------

function homePage(books) {
  const reading = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  const renderBook = (b) => `
    <div class="book">
      <div>
        <a href="/books/${esc(b.id)}"><strong>${esc(b.title)}</strong></a>
        <span class="meta">by ${esc(b.author)}</span>
      </div>
      <div class="actions">
        ${b.finished
          ? ''
          : `<form method="post" action="/books/${esc(b.id)}/finish"><button class="secondary" type="submit">Mark finished</button></form>`}
      </div>
    </div>`;

  const addForm = `
    <form method="post" action="/books">
      <h2 style="margin-top:0">Add a book</h2>
      <label for="title">Title</label>
      <input id="title" name="title" required maxlength="300">
      <label for="author">Author</label>
      <input id="author" name="author" required maxlength="200">
      <label for="notes">Notes</label>
      <textarea id="notes" name="notes" maxlength="5000" placeholder="Optional thoughts before you start..."></textarea>
      <button type="submit">Add book</button>
    </form>`;

  const readingSection = `
    <h2>Currently reading (${reading.length})</h2>
    ${reading.length ? reading.map(renderBook).join('') : '<p class="empty">Nothing in progress yet.</p>'}`;

  const finishedSection = `
    <h2>Finished (${finished.length})</h2>
    ${finished.length ? finished.map(renderBook).join('') : '<p class="empty">Nothing finished yet.</p>'}`;

  return layout('Home', addForm + readingSection + finishedSection);
}

function bookPage(book, req) {
  if (!book) return null;
  const host = req.headers.host || `localhost:${PORT}`;
  const shareUrl = `http://${host}/books/${book.id}`;
  const body = `
    <div class="back"><a href="/">← All books</a></div>
    <h2 style="margin-top:0">${esc(book.title)}</h2>
    <p class="meta">by ${esc(book.author)}</p>
    <p><strong>Status:</strong> ${book.finished ? 'Finished' : 'Currently reading'}</p>
    <h3>Notes</h3>
    <div>${book.notes ? escMulti(book.notes) : '<span class="muted">No notes yet.</span>'}</div>
    <div class="actions" style="margin-top:1.5rem">
      ${book.finished ? '' : `<form method="post" action="/books/${esc(book.id)}/finish"><button type="submit">Mark finished</button></form>`}
    </div>
    <div class="share">
      <label for="share" style="margin-top:0">Share link to this book</label>
      <input id="share" readonly value="${esc(shareUrl)}" onclick="this.select()">
    </div>`;
  return layout(book.title, body);
}

// --- Request helpers -------------------------------------------------------

/** @param {import('node:http').IncomingMessage} req */
function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('error', reject);
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
  });
}

function parseFormUrlencoded(text) {
  const params = {};
  for (const pair of text.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const key = decodeURIComponent((eq === -1 ? pair : pair.slice(0, eq)).replace(/\+/g, ' '));
    const val = decodeURIComponent((eq === -1 ? '' : pair.slice(eq + 1)).replace(/\+/g, ' '));
    params[key] = val;
  }
  return params;
}

function send(res, status, body, headers = {}) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', ...headers });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function notFound(res) {
  send(res, 404, layout('Not found', '<p>No such book.</p><p><a href="/">← Home</a></p>'));
}

// --- Server ----------------------------------------------------------------

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    const { pathname } = url;

    // Home
    if (req.method === 'GET' && pathname === '/') {
      const books = await loadBooks();
      return send(res, 200, homePage(books));
    }

    // Add a book
    if (req.method === 'POST' && pathname === '/books') {
      const form = parseFormUrlencoded(await readBody(req));
      const title = (form.title || '').trim();
      const author = (form.author || '').trim();
      if (!title || !author) {
        return send(res, 400, layout('Missing', '<p>Title and author are required.</p><p><a href="/">← Back</a></p>'));
      }
      const books = await loadBooks();
      const book = {
        id: randomUUID(),
        title,
        author,
        notes: (form.notes || '').trim(),
        finished: false,
        addedAt: new Date().toISOString(),
      };
      books.push(book);
      await saveBooks(books);
      return redirect(res, `/books/${book.id}`);
    }

    // Mark finished
    const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const id = finishMatch[1];
      const books = await loadBooks();
      const book = books.find((b) => b.id === id);
      if (!book) return notFound(res);
      book.finished = true;
      await saveBooks(books);
      return redirect(res, `/books/${id}`);
    }

    // Book detail (shareable link)
    const detailMatch = pathname.match(/^\/books\/([^/]+)$/);
    if (req.method === 'GET' && detailMatch) {
      const id = detailMatch[1];
      const books = await loadBooks();
      const page = bookPage(books.find((b) => b.id === id), req);
      if (!page) return notFound(res);
      return send(res, 200, page);
    }

    return notFound(res);
  } catch (err) {
    console.error(err);
    return send(res, 500, layout('Error', `<p>Something went wrong.</p><pre>${esc(err && err.message ? err.message : String(err))}</pre>`));
  }
});

server.listen(PORT, () => {
  const target = existsSync(DATA_FILE) ? DATA_FILE : join(process.cwd(), 'books.json');
  console.log(`Book tracker running at http://localhost:${PORT}`);
  console.log(`Saving books to ${target}`);
});
"}

